SETUP_TEMPLATE="from pathlib import Path\nimport datetime,hashlib,json,os,signal,subprocess,sys,time,traceback\nif SOURCE_SHA is None:\n    raise RuntimeError('UNPUBLISHED_DRAFT: publish reviewed source and rebuild with its immutable SHA before Run all')\nif not isinstance(SOURCE_SHA,str) or len(SOURCE_SHA)!=40:\n    raise RuntimeError('immutable 40-character source SHA required')\nSTAMP=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')\nOUTPUT=Path('/content/drive/MyDrive/Video-WM/Trajectory-Payload-Framewise-Sync-M05')/STAMP\nOUTPUT.mkdir(parents=True,exist_ok=False)\nRUN_OUTPUT=OUTPUT/'fixed_reference'\nREPO=Path('/content/SC-SSTW-TRAJECTORY-PAYLOAD-FRAMEWISE-SYNC-M05-'+STAMP)\nPYTHON=sys.executable\ndef write_json(path,value):\n    tmp=path.with_suffix(path.suffix+'.tmp');tmp.write_text(json.dumps(value,indent=2)+'\\n');os.replace(tmp,path)\ndef failed(stage,exc):\n    captured_traceback=''.join(traceback.format_exception(type(exc),exc,exc.__traceback__))\n    write_json(OUTPUT/'setup_failure.json',dict(stage=stage,error=f'{type(exc).__name__}: {exc}',traceback=captured_traceback,fixed_denominator=FIXED))\ndef logged(command,stage,cwd=None,check=True):\n    child=None;code=None;primary=None;primary_tb=None;cleanup_errors=[]\n    def retain_cleanup_error(label,exc):\n        nonlocal primary,primary_tb\n        if primary is None and not isinstance(exc,Exception):\n            primary=exc;primary_tb=exc.__traceback__\n        else:\n            cleanup_errors.append(label+': '+repr(exc))\n    try:\n        with (OUTPUT/'execution.log').open('a') as log:\n            log.write('COMMAND '+repr(command)+'\\n');log.flush()\n            popen_group={'start_new_session':True} if os.name=='posix' else {}\n            child=subprocess.Popen(command,cwd=cwd,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,bufsize=1,**popen_group)\n            try:\n                for line in child.stdout:\n                    print(line,end='',flush=True);log.write(line);log.flush()\n                code=child.wait()\n            except BaseException as exc:\n                primary=exc;primary_tb=exc.__traceback__\n            finally:\n                if child is not None:\n                    if os.name=='posix':\n                        pgid=child.pid\n                        try:os.killpg(pgid,signal.SIGTERM)\n                        except ProcessLookupError:pass\n                        except BaseException as exc:retain_cleanup_error('group SIGTERM',exc)\n                        try:\n                            deadline=time.monotonic()+5.0\n                            while time.monotonic()<deadline:\n                                try:os.killpg(pgid,0)\n                                except ProcessLookupError:break\n                                except BaseException as exc:\n                                    retain_cleanup_error('group probe',exc);break\n                                time.sleep(0.05)\n                        except BaseException as exc:\n                            retain_cleanup_error('group TERM grace',exc)\n                        finally:\n                            try:os.killpg(pgid,signal.SIGKILL)\n                            except ProcessLookupError:pass\n                            except BaseException as exc:retain_cleanup_error('group SIGKILL',exc)\n                    elif child.poll() is None:\n                        try:child.terminate()\n                        except ProcessLookupError:pass\n                        except BaseException as exc:retain_cleanup_error('terminate',exc)\n                    try:\n                        try:code=child.wait(timeout=10)\n                        except subprocess.TimeoutExpired:\n                            try:child.kill()\n                            except ProcessLookupError:pass\n                            except BaseException as exc:retain_cleanup_error('kill',exc)\n                            try:code=child.wait(timeout=10)\n                            except BaseException as exc:retain_cleanup_error('wait after kill',exc)\n                        except BaseException as exc:retain_cleanup_error('wait',exc)\n                    finally:\n                        if child.stdout is not None:\n                            try:child.stdout.close()\n                            except BaseException as exc:retain_cleanup_error('stdout close',exc)\n            if primary is None and not cleanup_errors:\n                log.write('EXIT '+str(code)+'\\n');log.flush()\n    except BaseException as wrapper_error:\n        if primary is None:\n            primary=wrapper_error;primary_tb=wrapper_error.__traceback__\n        elif wrapper_error is not primary:\n            cleanup_errors.append('log wrapper/close: '+repr(wrapper_error))\n    if primary is None and cleanup_errors:\n        primary=RuntimeError('process cleanup failed: '+'; '.join(cleanup_errors))\n        primary_tb=primary.__traceback__\n    if primary is None and check and code:\n        primary=subprocess.CalledProcessError(code,command)\n        primary_tb=primary.__traceback__\n    if primary is not None:\n        if cleanup_errors and hasattr(primary,'add_note'):\n            primary.add_note('secondary cleanup errors: '+'; '.join(cleanup_errors))\n        try:failed(stage,primary)\n        except BaseException as record_error:\n            if hasattr(primary,'add_note'):primary.add_note('failure record error: '+repr(record_error))\n        raise primary.with_traceback(primary_tb)\n    return code\nwrite_json(OUTPUT/'setup_receipt.json',dict(status='SETUP_STARTED',source_sha=SOURCE_SHA,fixed_denominator=FIXED))\n"
ENVIRONMENT_TEMPLATE="try:\n    logged(['git','clone','--filter=blob:none','https://github.com/RICHAAARC/SC-SSTW.git',str(REPO)],'SOURCE_CLONE')\n    logged(['git','-C',str(REPO),'fetch','origin',SOURCE_SHA],'SOURCE_FETCH')\n    logged(['git','-C',str(REPO),'checkout','--detach',SOURCE_SHA],'SOURCE_CHECKOUT')\n    actual=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip()\n    dirty=subprocess.check_output(['git','-C',str(REPO),'status','--porcelain'],text=True)\n    if actual!=SOURCE_SHA or dirty:raise RuntimeError('source SHA/clean checkout mismatch')\n    import shutil\n    if any(shutil.which(name) is None for name in ('ffmpeg','ffprobe')):\n        logged(['apt-get','update'],'MEDIA_TOOL_UPDATE',check=False)\n        logged(['apt-get','install','-y','ffmpeg'],'MEDIA_TOOL_REPAIR',check=False)\n    if logged([PYTHON,'-c','import torch; print(torch.__version__)'],'TORCH_PROBE',check=False):\n        logged([PYTHON,'-m','pip','install','--upgrade','torch'],'TORCH_REPAIR')\n    probe='from diffusers import AutoencoderKL,AutoencoderKLWan; print(AutoencoderKL.__name__,AutoencoderKLWan.__name__)'\n    if logged([PYTHON,'-c',probe],'VAE_IMPORT_PROBE',check=False):\n        logged([PYTHON,'-m','pip','install','diffusers>=0.35.1,<0.40','transformers>=4.45,<5','accelerate>=0.34','safetensors>=0.4.5'],'VAE_DEPENDENCY_REPAIR')\n    dependency_code=logged([PYTHON,'-m','pip','check'],'DEPENDENCY_REPORT',check=False)\n    (OUTPUT/'environment_freeze.txt').write_text(subprocess.check_output([PYTHON,'-m','pip','freeze'],text=True))\n    write_json(OUTPUT/'source_receipt.json',dict(source_sha=actual,clean=True))\n    write_json(OUTPUT/'setup_receipt.json',dict(status='SETUP_COMPLETE',source_sha=actual,fixed_denominator=FIXED,dependency_check_returncode=dependency_code))\nexcept Exception as exc:\n    try:failed('SOURCE_OR_ENVIRONMENT',exc)\n    except BaseException as record_error:\n        if hasattr(exc,'add_note'):exc.add_note('failure record error: '+repr(record_error))\n    raise\n"
RUN_TEMPLATE="try:\n    from google.colab import userdata\n    token=userdata.get('HF_TOKEN')\n    if token:os.environ['HF_TOKEN']=token\nexcept Exception:pass\nfinally:token=None\ncommand=[PYTHON,'-u','-m','experiments.wan_state_clock.video_trajectory_payload_framewise_sync_v1_run','--output',str(RUN_OUTPUT)]\ntry:\n    returncode=logged(command,'FIXED_RUN',cwd=REPO,check=False)\n    RESULT_PATH=RUN_OUTPUT/'result.json'\n    write_json(OUTPUT/'execution_receipt.json',dict(command=command,returncode=returncode,result_path=str(RESULT_PATH),result_exists=RESULT_PATH.is_file()))\n    if not RESULT_PATH.is_file():raise RuntimeError('No runner result; fixed denominator retained')\nexcept Exception as exc:\n    try:failed('RUNNER',exc)\n    except BaseException as record_error:\n        if hasattr(exc,'add_note'):exc.add_note('failure record error: '+repr(record_error))\n    raise\n"
CONFIG=ROOT/"experiments/wan_state_clock/configs/video_trajectory_conditional_joint_v1.json"
OUTPUT=ROOT/"notebooks/video_trajectory_conditional_joint_v1_colab.ipynb"
DISPLAY="result=json.loads(RESULT_PATH.read_text())\nif result['source_sha']!=SOURCE_SHA or result['config_sha256']!=CONFIG_SHA or result['fixed_denominator']!=FIXED:raise RuntimeError('result source/config/denominator identity mismatch')\nprint('Runtime:',result['status'],'Stage:',result['stage'],'Counts:',result['counts'])\nprint('Scope:',result['receiver_scope'])\nprint('Calls:',result['calls'],'Preparation:',result.get('source_preparation_receipt'))\nprint('Seals:',{k:v for k,v in result.items() if k.endswith('_seal')})\nfor sid,estimate in sorted(result['estimates'].items()):print('Blind estimate:',sid,estimate)\nfor lid,row in sorted(result['posthoc'].items()):\n    print(lid,row.get('key_role'),row['status'],'bit_errors=',row.get('bit_errors'),'error_bits=',row.get('error_bits'),'final_margin=',row.get('final_margins'),'time_margin=',row.get('time_margins'),'estimated=',row.get('estimated_path'),'truth=',row.get('truth_path'),'path_correct=',row.get('absolute_path_correct'),'map_correct=',row.get('source_map_correct'),'/',row.get('source_map_denominator'),'phase_correct=',row.get('phase_correct'),'k_error=',row.get('k_signed_error'),'alias=',row.get('alias_of'),'interpretation=',row.get('conditional_interpretation'))\nfor lid,row in result['payload_reads'].items():print('Operation cost:',lid,row.get('operation_cost'))\nfor qid,row in result['quality'].items():print('Descriptive quality:',qid,row)\nprint('Descriptive mode differences:',result.get('mode_differences'))\nprint('Environment:',result['environment'],'Failures:',result['failures'])\nprint('Evidence ceiling:',result['evidence_ceiling'],'Result:',RESULT_PATH)\n"
def build(source_sha=None,output=OUTPUT):
    if source_sha is not None and not re.fullmatch('[0-9a-f]{40}',source_sha):raise ValueError('immutable source SHA')
    cfg=json.loads(CONFIG.read_text());pins=cfg['environment_pins']
    setup=SETUP_TEMPLATE.replace('Trajectory-Payload-Framewise-Sync-M05','Trajectory-Conditional-Joint-V1').replace('SC-SSTW-TRAJECTORY-PAYLOAD-FRAMEWISE-SYNC-M05-','SC-SSTW-TRAJECTORY-CONDITIONAL-JOINT-')
    before=ENVIRONMENT_TEMPLATE.split("    if logged([PYTHON,'-c','import torch;")[0]
    after='    dependency_code='+ENVIRONMENT_TEMPLATE.split('    dependency_code=',1)[1]
    probe="import importlib.metadata as m; pins="+repr(pins)+"; actual={k:m.version(k) for k in pins}; assert all(actual[k].split('+')[0]==v for k,v in pins.items()),actual; from diffusers import AutoencoderKL,AutoencoderKLWan,WanPipeline; import torch,sentencepiece,ftfy; print(actual)"
    env=before+'    probe='+repr(probe)+"\n    if logged([PYTHON,'-c',probe],'DEPENDENCY_PROBE',check=False):\n        logged([PYTHON,'-m','pip','install',"+','.join(repr(k+'=='+v) for k,v in pins.items())+"],'PINNED_REPAIR')\n        logged([PYTHON,'-c',probe],'DEPENDENCY_REPROBE')\n"+after
    run="CONFIG_PATH=REPO/'experiments/wan_state_clock/configs/video_trajectory_conditional_joint_v1.json'\nCONFIG_SHA=hashlib.sha256(CONFIG_PATH.read_bytes()).hexdigest()\nconfiguration=json.loads(CONFIG_PATH.read_text())\nif configuration['name']!='video_trajectory_conditional_joint_v1' or configuration['fixed_denominator']!=FIXED:raise RuntimeError('fixed configuration mismatch')\n"+RUN_TEMPLATE.replace('experiments.wan_state_clock.video_trajectory_payload_framewise_sync_v1_run','experiments.wan_state_clock.video_trajectory_conditional_joint_v1_run').replace("'--output',str(RUN_OUTPUT)","'--config',str(CONFIG_PATH),'--output',str(RUN_OUTPUT)")
    note='Published source: '+source_sha if source_sha else 'UNPUBLISHED DRAFT: SOURCE_SHA=None; publish reviewed source then bind before Run all.'
    markdown='# Conditional trajectory-payload + terminal-M05 joint recovery\n\nOne fixed Run-all: regenerate the already-seen yellow-sailboat prompt / seed 2026100701 with PAYLOAD_MULTI 50 native steps (25 payload controls), release transformer then native decode. Separate matched P1/M05 worker: one shared unmodified framewise latent, target .5, two full MP4 codecs (P1/M05), no P0 codec or crop re-codec. This is a development source, not independent confirmation.\n\nPreserve phase1 (12), phase2/3 (16), and C/D single deletion (16) original logical reads: 44 = 40 blind + 4 oracle, 1605120 votes / 53504 time-bit / 1408 final-bit. Nine logical observations use eight overlapping same-source physical inputs. Fresh framewise receiver: 1156 frames / 151 batch8 batches / 18 scores / 3426 candidates. Original global score and single-jump H0 floating reductions stay separate; actual complete-map/key aliases deduplicate only computation. Conservative maximum 30 Wan encodes / 40 physical reads (blind 28 / 36); failures and unresolved slots retained, no cached retry.\n\nReceiver knows received RGB/key/predeclared protocol, not crop/deletion truth, writer evidence or message. All blind payload seals precede oracle maps; oracle seal precedes message evaluation. Original R44 for FULL181/177 and R22 for89, zero/tie/Counter unchanged. FULL is geometry only; oracle/aliases are not independent blind successes. K0 primary requires correct unique blind path/phase and 32 correct bits; RAW/GLOBAL controls need not be error-free. K1 is descriptive, no FPR/rejection threshold.\n\nSix descriptive quality rows preserve native P0 (already trajectory-watermarked), matched P1/M05 and exact reference identities. No numeric quality gate, no new quality model. Stage1 false authorization remains a counterexample, but arbitrary-video detection is not a prerequisite for this conditional task. No Stage1 gate/threshold, no source selection/retry or automatic paper experiment.\n\nThis main release has CPU/fake/schema/portability validation, including a synthetic CPU FFmpeg fixture. The retained fixed real evidence remains bound to source ac111d0fed253767651929d115c343fe1636c525; user Run all executes the real model/media chain after immutable source publication.\n\n'+note
    sources=[('code',"from google.colab import drive\ndrive.mount('/content/drive')\n"),('markdown',markdown),('code',f'SOURCE_SHA = {source_sha!r}\nFIXED = {cfg["fixed_denominator"]!r}\n'+setup),('code',env),('code',run),('code',DISPLAY)]
    cells=[]
    for i,(kind,source) in enumerate(sources):
        row=dict(cell_type=kind,id='conditional-joint-'+str(i),metadata={},source=source.splitlines(keepends=True))
        if kind=='code':ast.parse(source);row.update(execution_count=None,outputs=[])
        cells.append(row)
    nb=dict(nbformat=4,nbformat_minor=5,cells=cells,metadata=dict(kernelspec=dict(display_name='Python 3',language='python',name='python3'),language_info=dict(name='python'),candidate_binding=dict(candidate='trajectory-conditional-joint-v1',source_sha=source_sha,status='UNPUBLISHED_DRAFT' if source_sha is None else 'PUBLISHED_SHA_BOUND')))
    Path(output).write_text(json.dumps(nb,indent=1)+'\n');return Path(output)
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--source-sha');p.add_argument('--output',type=Path,default=OUTPUT);a=p.parse_args();print(build(a.source_sha,a.output))
